{"implementation":"def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    edges = []
    for u, v, d in distances:
        mr = max(core_dist[u], core_dist[v], d)
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    selected = []
    total = 0.0
    for mr, u, v in edges:
        if union(u, v):
            selected.append([u, v, mr])
            total += mr
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError("disconnected input")
    return {"edges": selected, "total_weight": total}"}
